#!/bin/sh

set -eu

SCRIPT_DIR=$(CDPATH= cd -- "$(dirname -- "$0")" && pwd)
. "$SCRIPT_DIR/common.sh"

ensure_output_dirs
wrapper=$BUILD_DIR/evaluation-wrapper.tex
cat >"$wrapper" <<'EOF'
% Generated by scripts/evaluation.sh; do not edit.
\providecommand{\EvaluationBuildtrue}{}
\EvaluationBuildtrue
\input{main.tex}
EOF

say 'Building evaluation variant...'
run_latexmk -jobname=evaluation "$wrapper"
[ -f "$BUILD_DIR/evaluation.pdf" ] || fail 'build/evaluation.pdf was not generated'
log=$BUILD_DIR/evaluation.log
[ -f "$log" ] || fail 'build/evaluation.log was not generated'
issues=$BUILD_DIR/evaluation-check-issues.txt
if grep -E 'LaTeX Warning: (There were undefined references|Reference .+ undefined)|LaTeX Error:|Package .* Error:|Undefined control sequence|Emergency stop|Fatal error occurred|Overfull \\hbox' "$log" >"$issues"; then
    printf '\nEvaluation quality issues:\n' >&2
    cat "$issues" >&2
    fail 'evaluation build contains LaTeX errors, unresolved references, or overfull boxes'
fi
rm -f "$issues"
"$SCRIPT_DIR/publish-pdf.sh" "$BUILD_DIR/evaluation.pdf"
say 'Evaluation build complete: dist/evaluation.pdf'
